// MARK: - motion

extension Tokens {
    /// Nhóm `motion`. Motion style E, chép từ helmet của canvas. Keyframe theo CSS: thuộc tính vắng ở một mốc thì nội suy giữa hai mốc gần nhất có nó; easing áp cho từng đoạn giữa hai mốc. translate pt, rotate độ, scale bội số, opacity 0–1.
    public enum Motion {
        /// Nhóm `motion.preset`.
        public enum Preset {
            /// `motion.preset.lay` (460 ms, cubic-bezier(0.2, 0.8, 0.2, 1))
            /// Đặt giấy xuống: lượt hiện của màn, theo thứ tự đọc.
            public static let lay: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.46,
                easing: Tokens.CubicBezier(0.2, 0.8, 0.2, 1),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(opacity: 0, translateY: -12, scale: 1.03)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(opacity: 1, translateY: 0, scale: 1)),
                ]
            )

            /// `motion.preset.rise` (440 ms, cubic-bezier(0.2, 0.8, 0.2, 1))
            /// Tờ giấy trượt lên từ đáy khi báo kết quả đúng. translate_y_percent tính theo chiều cao chính nó.
            public static let rise: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.44,
                easing: Tokens.CubicBezier(0.2, 0.8, 0.2, 1),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(translateYPercent: 105)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(translateYPercent: 0)),
                ]
            )

            /// `motion.preset.stamp` (520 ms, cubic-bezier(0.3, 0.7, 0.3, 1))
            /// Đóng triện khi chọn hoặc khi báo đúng.
            public static let stamp: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.52,
                easing: Tokens.CubicBezier(0.3, 0.7, 0.3, 1),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(opacity: 0, scale: 1.7)),
                    Tokens.Keyframe(offset: 0.55, pose: Tokens.Pose(opacity: 1, scale: 0.9)),
                    Tokens.Keyframe(offset: 0.78, pose: Tokens.Pose(scale: 1.06)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(opacity: 1, scale: 1)),
                ]
            )

            /// `motion.preset.pop` (380 ms, cubic-bezier(0.3, 0.7, 0.3, 1.2))
            /// Mảnh nhỏ bật ra (hình đổi theo lựa chọn, món vào mâm, huy hiệu).
            public static let pop: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.38,
                easing: Tokens.CubicBezier(0.3, 0.7, 0.3, 1.2),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(opacity: 0, scale: 0.4)),
                    Tokens.Keyframe(offset: 0.7, pose: Tokens.Pose(opacity: 1, scale: 1.12)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(opacity: 1, scale: 1)),
                ]
            )

            /// `motion.preset.fall` (950 ms, cubic-bezier(0.2, 0.7, 0.3, 1))
            /// Giấy vụn rơi. Chỉ màn Thưởng.
            public static let fall: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.95,
                easing: Tokens.CubicBezier(0.2, 0.7, 0.3, 1),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(opacity: 0, translateY: -70, rotate: .degrees(-50))),
                    Tokens.Keyframe(offset: 0.15, pose: Tokens.Pose(opacity: 1)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(opacity: 1, translateY: 0, rotate: .degrees(0))),
                ]
            )

            /// `motion.preset.slide` (360 ms, cubic-bezier(0.2, 0.8, 0.2, 1))
            /// Mảnh trượt vào từ phải: gợi ý, mẩu giấy báo sai, bước tiếp theo.
            public static let slide: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.36,
                easing: Tokens.CubicBezier(0.2, 0.8, 0.2, 1),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(opacity: 0, translateX: 28)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(opacity: 1, translateX: 0)),
                ]
            )

            /// `motion.preset.grow` (620 ms, cubic-bezier(0.2, 0.8, 0.2, 1))
            /// Cột mọc từ đáy (biểu đồ phút học ở Góc phụ huynh).
            public static let grow: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.62,
                easing: Tokens.CubicBezier(0.2, 0.8, 0.2, 1),
                delay: 0,
                stagger: true,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 1),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(scaleX: 1, scaleY: 0)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(scaleX: 1, scaleY: 1)),
                ]
            )

            /// `motion.preset.sway` (3600 ms, cubic-bezier(0.42, 0, 0.58, 1), lặp)
            /// Lắc nhẹ lặp (mascot, cây). Tính là chuyển động lặp duy nhất của màn. easing là ease-in-out của CSS.
            public static let sway: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 3.6,
                easing: Tokens.CubicBezier(0.42, 0, 0.58, 1),
                delay: 0,
                stagger: false,
                repeats: true,
                fillMode: .none,
                origin: UnitPoint(x: 0.5, y: 1),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(rotate: .degrees(-3))),
                    Tokens.Keyframe(offset: 0.5, pose: Tokens.Pose(rotate: .degrees(3))),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(rotate: .degrees(-3))),
                ]
            )

            /// `motion.preset.nudge` (2800 ms, cubic-bezier(0.42, 0, 0.58, 1), trễ 1200 ms, lặp)
            /// Nhắc chạm lặp, chờ 1,2 s mới bắt đầu (nút 'Bắt đầu bài 1'). Tính là chuyển động lặp của màn.
            public static let nudge: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 2.8,
                easing: Tokens.CubicBezier(0.42, 0, 0.58, 1),
                delay: 1.2,
                stagger: false,
                repeats: true,
                fillMode: .none,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(translateY: 0)),
                    Tokens.Keyframe(offset: 0.2, pose: Tokens.Pose(translateY: -5)),
                    Tokens.Keyframe(offset: 0.4, pose: Tokens.Pose(translateY: 0)),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(translateY: 0)),
                ]
            )

            /// `motion.preset.turn` (420 ms, cubic-bezier(0.2, 0.8, 0.2, 1))
            /// Thẻ sưu tầm quay mặt ra khi nhận. Chỉ có ở helmet màn Thưởng (ngoài bộ 11 preset chung).
            public static let turn: Tokens.KeyframeAnimation = Tokens.KeyframeAnimation(
                duration: 0.42,
                easing: Tokens.CubicBezier(0.2, 0.8, 0.2, 1),
                delay: 0,
                stagger: false,
                repeats: false,
                fillMode: .backwards,
                origin: UnitPoint(x: 0.5, y: 0.5),
                keyframes: [
                    Tokens.Keyframe(offset: 0, pose: Tokens.Pose(opacity: 0.3, rotateY: .degrees(90))),
                    Tokens.Keyframe(offset: 1, pose: Tokens.Pose(opacity: 1, rotateY: .degrees(0))),
                ]
            )

            /// `motion.preset.press` (120 ms, cubic-bezier(0.25, 0.1, 0.25, 1))
            /// Ấn giấy xuống 3pt khi giữ (CSS :active). Đổi bóng và màu nền khi đổi trạng thái chạy 160 ms. easing là ease của CSS.
            public static let press: Tokens.StateTransition = Tokens.StateTransition(
                duration: 0.12,
                easing: Tokens.CubicBezier(0.25, 0.1, 0.25, 1),
                delay: 0,
                trigger: .pressed,
                from: Tokens.Pose(translateY: 0),
                to: Tokens.Pose(translateY: 3),
                also: [
                    Tokens.StateTransition.Companion(property: .shadow, duration: 0.16, easing: Tokens.CubicBezier(0.25, 0.1, 0.25, 1)),
                    Tokens.StateTransition.Companion(property: .backgroundColor, duration: 0.16, easing: Tokens.CubicBezier(0.25, 0.1, 0.25, 1)),
                ],
                preserve3d: false
            )

            /// `motion.preset.flip` (560 ms, cubic-bezier(0.3, 0.7, 0.3, 1))
            /// Lật thẻ 3D (Bộ thẻ, Từ vựng). Mặt sau xoay sẵn 180 độ, ẩn mặt lưng.
            public static let flip: Tokens.StateTransition = Tokens.StateTransition(
                duration: 0.56,
                easing: Tokens.CubicBezier(0.3, 0.7, 0.3, 1),
                delay: 0,
                trigger: .state,
                from: Tokens.Pose(rotateY: .degrees(0)),
                to: Tokens.Pose(rotateY: .degrees(180)),
                also: [
                    Tokens.StateTransition.Companion(property: .translate, duration: 0.12, easing: Tokens.CubicBezier(0.25, 0.1, 0.25, 1)),
                ],
                preserve3d: true
            )
        }

        /// Nhóm `motion.stagger`. Độ trễ --d giữa các mảnh giấy trong lượt hiện. Chỉ áp cho preset có stagger = true.
        public enum Stagger {
            /// `motion.stagger.step` (60 ms)
            /// Bậc giữa hai khối liền nhau theo thứ tự đọc (canvas 60, có màn 70).
            public static let step: TimeInterval = 0.06

            /// `motion.stagger.step_dense` (40 ms)
            /// Bậc giữa các ô trong một lưới (Quiz).
            public static let stepDense: TimeInterval = 0.04

            /// `motion.stagger.max_delay` (500 ms)
            /// Mảnh cuối bắt đầu chậm nhất ~0,5 s sau khi vào màn; xong hẳn ~1 s (cộng duration). Màn Thưởng ngoại lệ vì giấy vụn.
            public static let maxDelay: TimeInterval = 0.5
        }

        /// Nhóm `motion.rules`. Luật motion style E (designer.md, B7.5).
        public enum Rules {
            /// `motion.rules.reveal_per_screen`
            /// Mỗi màn đúng một lượt hiện.
            public static let revealPerScreen: Int = 1

            /// `motion.rules.max_loops_per_screen`
            /// Tối đa một chuyển động lặp (sway hoặc nudge) mỗi màn.
            public static let maxLoopsPerScreen: Int = 1

            /// `motion.rules.wrong_answer_shake`
            /// Sai không rung, không dấu X đỏ.
            public static let wrongAnswerShake: Bool = false

            /// `motion.rules.confetti_screen`
            /// Preset fall chỉ chạy ở màn Thưởng.
            public static let confettiScreen: String = "reward"

            /// `motion.rules.reduce_motion`
            /// Bật Giảm chuyển động: tắt hết preset, kể cả press và flip; trạng thái đổi tức thì, mảnh giấy hiện ngay ở trạng thái cuối.
            public static let reduceMotion: String = "disable_all"
        }
    }
}

