// MARK: - Age group lookups

extension Tokens.AgeGroup {
    /// Corner radius of this age group (`radius.*`).
    public var radius: CGFloat {
        switch self {
        case .explorer: Tokens.Radius.explorer
        case .discoverer: Tokens.Radius.discoverer
        case .scientist: Tokens.Radius.scientist
        }
    }

    /// Minimum touch target of this age group (`touch_target.*`), pt.
    public var touchTarget: CGFloat {
        switch self {
        case .explorer: Tokens.TouchTarget.explorer
        case .discoverer: Tokens.TouchTarget.discoverer
        case .scientist: Tokens.TouchTarget.scientist
        }
    }

    /// World colour of this age group (`color.age_group.*`).
    public var color: Color {
        switch self {
        case .explorer: Tokens.AgeGroupColor.explorer
        case .discoverer: Tokens.AgeGroupColor.discoverer
        case .scientist: Tokens.AgeGroupColor.scientist
        }
    }
}
